import sys
input = sys.stdin.readline

# Every node is also remembered in this list. Python in the browser cannot free a very long chain of nodes at once,
# so free_nodes() (called at the end) cuts the links first and the nodes are then freed one by one.
all_nodes = []


class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next
        all_nodes.append(self)


def free_nodes():
    for node in all_nodes:
        node.next = None
        if hasattr(node, "random"):
            node.random = None
    all_nodes.clear()


# Builds a list from the values. If pos is 0 or more, the last node points back to the node at index pos (a cycle).
def build_list(values, pos=-1):
    head = None
    for v in reversed(values):
        head = ListNode(v, head)
    if pos >= 0:
        tail = head
        while tail.next is not None:
            tail = tail.next
        target = head
        for _ in range(pos):
            target = target.next
        tail.next = target
    return head


# Prints the values of a list on one line ("empty" for an empty list).
def print_list(head):
    out = []
    while head is not None:
        out.append(head.val)
        head = head.next
    print(*(out if out else ["empty"]))


def merge_two(a, b):
    dummy = ListNode(0)
    tail = dummy
    while a is not None and b is not None:
        if a.val <= b.val:
            tail.next = a
            a = a.next
        else:
            tail.next = b
            b = b.next
        tail = tail.next
    tail.next = a if a is not None else b
    return dummy.next


def sort_list(head):
    if head is None or head.next is None:
        return head
    slow, fast = head, head.next
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
    second = slow.next
    slow.next = None
    return merge_two(sort_list(head), sort_list(second))

n = int(input())
a = list(map(int, input().split()))

print_list(sort_list(build_list(a)))
free_nodes()

